CREATE TABLE IF NOT EXISTS kajian (id CHAR(36) PRIMARY KEY,title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,description TEXT NOT NULL,speaker VARCHAR(180) NULL,start_at DATETIME(6) NOT NULL,end_at DATETIME(6) NULL,location VARCHAR(255) NULL,map_url VARCHAR(1024) NULL,live_url VARCHAR(1024) NULL,poster_url VARCHAR(1024) NULL,status VARCHAR(32) NOT NULL DEFAULT 'UPCOMING',published BOOLEAN NOT NULL DEFAULT FALSE,created_by CHAR(36) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),INDEX idx_kajian_start(start_at),INDEX idx_kajian_pub(published,start_at));
CREATE TABLE IF NOT EXISTS contents (id CHAR(36) PRIMARY KEY,type VARCHAR(40) NOT NULL,title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,summary TEXT NULL,body LONGTEXT NULL,image_url VARCHAR(1024) NULL,published BOOLEAN NOT NULL DEFAULT FALSE,published_at DATETIME(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_content_type_pub(type,published,published_at));
